 if tag=='md-segmented-button':
  components[tag]['appearance']={'api':'AWCSegmentedButtonAppearance / AWCSegmentedButtonAppearanceScope','fields':'containerColor selectedContainerColor labelColor selectedLabelColor outlineColor cornerRadius iconSize'.split()}
