  components[tag]['visualParts']=['surface', 'message', 'actions', 'close', 'close-icon']
  components[tag]['notes']=['Dedicated native Snackbar supports all eleven source properties, three lifecycle events, two retained controller methods and three actual authored slots. AWCSnackbarScope supplies the viewport and peer order; native timers, hover/focus, Escape and retained Laboratory resize follow source behavior. Seven typed appearance hooks and five part targets are implemented. Original and supplemental geometry/paint, default-palette, motion and lifecycle gates pass; final Laboratory acceptance remains separate in the audit. CSS syntax, native accessibility and rasterization boundaries remain documented.']
